import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    a = []
    for _ in range(n):
        a.append(int(data[idx])); idx += 1
    k = int(data[idx]); idx += 1
    bad = []
    for _ in range(k):
        bad.append(int(data[idx])); idx += 1

    MOD = 1000000007
    total_sum = sum(a)

    if k == 0:
        fact_n = 1
        from collections import Counter
        cnt = Counter(a)
        for x in cnt.values():
            f = 1
            for i in range(1, x + 1):
                f = (f * i) % MOD
            fact_n = (fact_n * pow(f, MOD - 2, MOD)) % MOD
        f_n = 1
        for i in range(1, n + 1):
            f_n = (f_n * i) % MOD
        ans = (f_n * fact_n) % MOD
        print(ans)
        return

    bad_set = set(bad)
    bad.sort()

    memo = {}

    def solve(mask, current_pos):
        if current_pos in bad_set:
            return 0
        if mask == (1 << n) - 1:
            return 1

        state = (mask, current_pos)
        if state in memo:
            return memo[state]

        res = 0
        for i in range(n):
            if not (mask & (1 << i)):
                new_pos = current_pos + a[i]
                if new_pos > total_sum:
                    continue
                if new_pos in bad_set:
                    continue
                if new_pos == total_sum:
                    if (mask | (1 << i)) == (1 << n) - 1:
                        res = (res + 1) % MOD
                else:
                    res = (res + solve(mask | (1 << i), new_pos)) % MOD
        memo[state] = res
        return res

    ans = solve(0, 0)
    print(ans)

if __name__ == "__main__":
    main()
